// Nested linked stock item for background inventory deductions
export interface LinkedStockItem {
  productId: string;
  partNo: string;
  description: string;
  qtyToDeduct: number;
  unit: string;
  categoryName?: string;
  subcategoryName?: string;
  threadType?: string;
  grade?: string;
  size?: string;
  finish?: string;
}

// Invoice items interface
interface InvoiceItem {
  id: string;
  sn: string | number;
  pltNo?: string; // PLT NO column
  description: string;
  unit: string;
  qty: number;
  unitPriceWOVAT: number | string;
  vatRate: number | string; // e.g. 5 for 5%, 0 for zero-rated
  userVatSet?: boolean;
  discount?: number;
  finish?: string; // Optional finish/grade indicator
  size?: string; // Optional size indicator
  grade?: string; // GRADE for packing lists
  hsCode?: string; // HS CODE for item list
  qtyPerBox?: number; // QTY/BOX/BUNDLE for packing lists
  numBoxes?: number; // NO/BOX BUNDLE for packing lists
  unitWeight?: number; // UNIT WEIGHT for packing lists
  boxNo?: string; // Box grouping identifier for merge (e.g. "Box 01")
  packagingType?: string; // "BOX" or "BUNDLE" for packing lists
  per?: string; // Pricing basis unit PER
  linkedStockItems?: LinkedStockItem[]; // Mapped internal standard stock items to deduct
  textColor?: string; // Excel-style font color for cell/row
}

export const getProductBalance = (productId: string): number => {
  let stds: Category[] = [];
  try {
    const savedStd = localStorage.getItem('mf_std_products');
    if (savedStd) stds = JSON.parse(savedStd);
  } catch (e) {}

  let fines: Category[] = [];
  try {
    const savedFine = localStorage.getItem('mf_fine_products');
    if (savedFine) fines = JSON.parse(savedFine);
  } catch (e) {}

  for (const c of stds) {
    for (const s of c.subcategories) {
      for (const t of s.threadTypes) {
        for (const g of t.grades) {
          const r = g.rows.find(row => row.id === productId);
          if (r) return r.balanceStock || 0;
        }
      }
    }
  }

  for (const c of fines) {
    for (const s of c.subcategories) {
      for (const t of s.threadTypes) {
        for (const g of t.grades) {
          const r = g.rows.find(row => row.id === productId);
          if (r) return r.balanceStock || 0;
        }
      }
    }
  }
  return 0;
};


export const formatProductSearchDisplay = (p: any, grade: string, category: string, subcategory: string, threadType: string, displayQty?: number) => {
  if (!p) return '';
  const catUpper = (category || '').toUpperCase();
  const subUpper = (subcategory || '').toUpperCase();
  const descUpper = (p.description || '').toUpperCase();
  
  const isFlangeBolt = catUpper.includes('FLANGE') || subUpper.includes('FLANGE') || descUpper.includes('FLANGE');
  const isHexBolt = catUpper.includes('HEX BOLT') || subUpper.includes('HEX BOLT') || descUpper.includes('HEX BOLT') || catUpper.includes('STRUCTURAL BOLT') || subUpper.includes('STRUCTURAL BOLT') || isFlangeBolt;
  const isNut = catUpper.includes('NUT') || subUpper.includes('NUT') || descUpper.includes('NUT');
  const isWasher = catUpper.includes('WASHER') || subUpper.includes('WASHER') || descUpper.includes('WASHER');

  // Extract grade short form (e.g. 4.6, 8.8, 10.9)
  let gradeStr = '';
  if (grade || p.grade) {
    const nameToMatch = grade || p.grade || '';
    const match = nameToMatch.match(/(4\.6|8\.8|10\.9|12\.9)/);
    if (match) {
      gradeStr = match[1];
    } else {
      gradeStr = nameToMatch.replace(/DIN\s*\d+/g, '').replace(/ISO\s*\d+/g, '').replace(/GR\s*/g, '').trim();
    }
  }

  // Determine thread type / threading code: FTM, HTM, FTI, HTI
  let threadAbbr = '';
  const combined = (catUpper + ' ' + subUpper + ' ' + (threadType || p.threadType || '').toUpperCase() + ' ' + (grade || p.grade || '').toUpperCase() + ' ' + descUpper);

  if (isHexBolt) {
    if (combined.includes('FULL') && (combined.includes('METRIC') || combined.includes('M'))) {
      threadAbbr = 'FTM';
    } else if (combined.includes('HALF') && (combined.includes('METRIC') || combined.includes('M'))) {
      threadAbbr = 'HTM';
    } else if (combined.includes('FULL') && (combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('INCHES') || combined.includes(' BSW') || combined.includes('UNC/UNF'))) {
      threadAbbr = 'FTI';
    } else if (combined.includes('HALF') && (combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('INCHES') || combined.includes(' BSW') || combined.includes('UNC/UNF'))) {
      threadAbbr = 'HTI';
    } else {
      // Fallback detection
      const isMetric = combined.includes('METRIC') || combined.includes(' M') || combined.startsWith('M') || combined.includes(' M ') || combined.includes('MM');
      const isInch = combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('BSW') || combined.includes('INCHES');
      const hasHalf = combined.includes('HALF');
      if (hasHalf) {
        threadAbbr = isInch ? 'HTI' : 'HTM';
      } else {
        threadAbbr = isInch ? 'FTI' : 'FTM';
      }
    }
  } else if (isNut || isWasher) {
    const isMetric = combined.includes('METRIC') || combined.includes(' M') || combined.startsWith('M') || combined.includes(' M ') || combined.includes('MM') || combined.includes('MT');
    const isInch = combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('BSW') || combined.includes('INCHES');
    if (isMetric) {
      threadAbbr = 'METRIC MT';
    } else if (isInch) {
      threadAbbr = 'INCHES IN';
    } else {
      threadAbbr = (threadType || p.threadType || '').toUpperCase();
    }
  } else {
    threadAbbr = (threadType || p.threadType || '').toUpperCase();
  }

  // Size formatting
  let sizeStr = '';
  if (p.dia && p.length) {
    sizeStr = `${p.dia} X ${p.length}`;
  } else {
    sizeStr = p.dia || p.length || p.size || '';
  }

  if (sizeStr) {
    sizeStr = sizeStr.toUpperCase().trim();
    sizeStr = sizeStr.replace(/\s+/g, ' ');
    const isMetric = threadAbbr.endsWith('M') || threadAbbr.endsWith('MT') || threadAbbr.includes('METRIC') || catUpper.includes('METRIC') || subUpper.includes('METRIC');
    if (isMetric && /^\d/.test(sizeStr)) {
      sizeStr = 'M' + sizeStr;
    }
    if (isMetric && !sizeStr.endsWith('MM')) {
      if (/^M?\d+\s*[X/x]\s*\d+(\s*MM)?$/i.test(sizeStr)) {
        sizeStr = sizeStr.replace(/\s*MM/i, '') + 'MM';
      }
    }
  }

  const pNo = (p.partNo || '').toUpperCase().trim();
  const pCat = (category || '').toUpperCase().trim();
  let pSub = (subcategory || '').toUpperCase().trim();
  if (pSub.startsWith(pCat) && pSub.length > pCat.length) {
    pSub = pSub.replace(pCat, '').trim();
  }
  const pThread = threadAbbr.toUpperCase().trim();
  const pGrade = (gradeStr || grade || p.grade || '').toUpperCase().trim();
  const pSize = sizeStr.toUpperCase().trim();
  const pFinish = (p.finish && !p.finish.toUpperCase().includes('SELF') && !p.finish.toUpperCase().includes('PLAIN')) ? p.finish.toUpperCase().trim() : 'SELF';

  const list: string[] = [];
  list.push(pNo || '—');
  list.push(pCat || '—');
  list.push(pSub || '—');
  list.push(pThread || '—');
  list.push(pGrade || '—');
  list.push(pSize || '—');
  list.push(pFinish || 'SELF');
  
  const qtyVal = displayQty !== undefined ? displayQty : (p.balanceStock !== undefined ? p.balanceStock : 0);
  list.push(`${qtyVal} ${p.unit || 'PCS.'}`);

  return list.join(' | ').trim();
};

export const formatStockItemDisplay = (st: LinkedStockItem) => {
  const catUpper = (st.categoryName || '').toUpperCase();
  const subUpper = (st.subcategoryName || '').toUpperCase();
  const descUpper = (st.description || '').toUpperCase();
  
  const isFlangeBolt = catUpper.includes('FLANGE') || subUpper.includes('FLANGE') || descUpper.includes('FLANGE');
  const isHexBolt = catUpper.includes('HEX BOLT') || subUpper.includes('HEX BOLT') || descUpper.includes('HEX BOLT') || catUpper.includes('STRUCTURAL BOLT') || subUpper.includes('STRUCTURAL BOLT') || isFlangeBolt;
  const isNut = catUpper.includes('NUT') || subUpper.includes('NUT') || descUpper.includes('NUT');
  const isWasher = catUpper.includes('WASHER') || subUpper.includes('WASHER') || descUpper.includes('WASHER');

  // Extract grade short form (e.g. 4.6, 8.8, 10.9)
  let gradeStr = '';
  if (st.grade) {
    const match = st.grade.match(/(4\.6|8\.8|10\.9|12\.9)/);
    if (match) {
      gradeStr = match[1];
    } else {
      // clean grade text of common prefixes
      gradeStr = st.grade.replace(/DIN\s*\d+/g, '').replace(/ISO\s*\d+/g, '').replace(/GR\s*/g, '').trim();
    }
  }

  // Determine thread type / threading code: FTM, HTM, FTI, HTI
  let threadAbbr = '';
  const combined = (catUpper + ' ' + subUpper + ' ' + (st.threadType || '').toUpperCase() + ' ' + (st.grade || '').toUpperCase() + ' ' + descUpper);

  if (isHexBolt) {
    if (combined.includes('FULL') && (combined.includes('METRIC') || combined.includes('M'))) {
      threadAbbr = 'FTM';
    } else if (combined.includes('HALF') && (combined.includes('METRIC') || combined.includes('M'))) {
      threadAbbr = 'HTM';
    } else if (combined.includes('FULL') && (combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('INCHES') || combined.includes(' BSW') || combined.includes('UNC/UNF'))) {
      threadAbbr = 'FTI';
    } else if (combined.includes('HALF') && (combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('INCHES') || combined.includes(' BSW') || combined.includes('UNC/UNF'))) {
      threadAbbr = 'HTI';
    } else {
      // Fallback detection
      const isMetric = combined.includes('METRIC') || combined.includes(' M') || combined.startsWith('M') || combined.includes(' M ') || combined.includes('MM');
      const isInch = combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('BSW') || combined.includes('INCHES');
      const hasHalf = combined.includes('HALF');
      if (hasHalf) {
        threadAbbr = isInch ? 'HTI' : 'HTM';
      } else {
        threadAbbr = isInch ? 'FTI' : 'FTM';
      }
    }
  } else if (isNut || isWasher) {
    const isMetric = combined.includes('METRIC') || combined.includes(' M') || combined.startsWith('M') || combined.includes(' M ') || combined.includes('MM') || combined.includes('MT');
    const isInch = combined.includes('INCH') || combined.includes('UNC') || combined.includes('UNF') || combined.includes('BSW') || combined.includes('INCHES');
    if (isMetric) {
      threadAbbr = 'METRIC MT';
    } else if (isInch) {
      threadAbbr = 'INCHES IN';
    } else {
      threadAbbr = (st.threadType || '').toUpperCase();
    }
  } else {
    threadAbbr = (st.threadType || '').toUpperCase();
  }

  // Size formatting: convert "12 x 50" to "M12 X 50MM" if metric, or similar clean format
  let sizeStr = st.size || '';
  if (sizeStr) {
    sizeStr = sizeStr.toUpperCase().trim();
    sizeStr = sizeStr.replace(/\s+/g, ' ');
    const isMetric = threadAbbr.endsWith('M') || threadAbbr.endsWith('MT') || threadAbbr.includes('METRIC') || catUpper.includes('METRIC') || subUpper.includes('METRIC');
    if (isMetric && /^\d/.test(sizeStr)) {
      sizeStr = 'M' + sizeStr;
    }
    if (isMetric && !sizeStr.endsWith('MM')) {
      if (/^M?\d+\s*[X/x]\s*\d+(\s*MM)?$/i.test(sizeStr)) {
        sizeStr = sizeStr.replace(/\s*MM/i, '') + 'MM';
      }
    }
  }

  // Uniform structured display layout matching user-requested order:
  // PART NO | CATEGORY|SUB CATEGORY|THREAD SERIES|GRADES|SIZE|FINISH|QTY
  const pNo = (st.partNo || '').toUpperCase().trim();
  const pCat = (st.categoryName || '').toUpperCase().trim();
  let pSub = (st.subcategoryName || '').toUpperCase().trim();
  if (pSub === pCat) {
    pSub = ''; // Avoid duplication if identical
  }
  const pThread = (threadAbbr || '').toUpperCase().trim();
  const pGrade = (gradeStr || '').toUpperCase().trim();
  const pSize = (sizeStr || '').toUpperCase().trim();
  const pFinish = (st.finish && !st.finish.toUpperCase().includes('SELF') && !st.finish.toUpperCase().includes('PLAIN')) ? st.finish.toUpperCase().trim() : 'SELF';

  const list: string[] = [];
  list.push(pNo || '—');
  list.push(pCat || '—');
  list.push(pSub || '—');
  list.push(pThread || '—');
  list.push(pGrade || '—');
  list.push(pSize || '—');
  list.push(pFinish || 'SELF');
  
  const qtyVal = st.qtyToDeduct !== undefined ? st.qtyToDeduct : 0;
  list.push(`${qtyVal} ${st.unit || 'PCS.'}`);

  return list.join(' | ').trim();
};

