  const handleMetadataGridKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const target = e.target as HTMLInputElement | HTMLSelectElement;
    if (!target || (target.tagName !== 'INPUT' && target.tagName !== 'SELECT')) return;

    if (!['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
      return;
    }

    const container = e.currentTarget;
    const focusables = Array.from(
      container.querySelectorAll('input:not([type="hidden"]), select')
    ) as Array<HTMLInputElement | HTMLSelectElement>;

    const currentIndex = focusables.indexOf(target);
    if (currentIndex === -1) return;

    const rect = target.getBoundingClientRect();
    const currentCenterX = rect.left + rect.width / 2;
    const currentCenterY = rect.top + rect.height / 2;

    let bestMatch: HTMLInputElement | HTMLSelectElement | null = null;
    let bestDistance = Infinity;

    if (e.key === 'ArrowUp') {
      focusables.forEach((el) => {
        if (el === target) return;
        const r = el.getBoundingClientRect();
        const cy = r.top + r.height / 2;
        const cx = r.left + r.width / 2;
        if (cy < currentCenterY - 4) {
          const dx = cx - currentCenterX;
          const dy = cy - currentCenterY;
          const dist = Math.abs(dx) * 1.5 + Math.abs(dy);
          if (dist < bestDistance) {
            bestDistance = dist;
            bestMatch = el;
          }
        }
      });
    } else if (e.key === 'ArrowDown') {
      focusables.forEach((el) => {
        if (el === target) return;
        const r = el.getBoundingClientRect();
        const cy = r.top + r.height / 2;
        const cx = r.left + r.width / 2;
        if (cy > currentCenterY + 4) {
          const dx = cx - currentCenterX;
          const dy = cy - currentCenterY;
          const dist = Math.abs(dx) * 1.5 + Math.abs(dy);
          if (dist < bestDistance) {
            bestDistance = dist;
            bestMatch = el;
          }
        }
      });
    } else if (e.key === 'ArrowLeft') {
      focusables.forEach((el) => {
        if (el === target) return;
        const r = el.getBoundingClientRect();
        const cy = r.top + r.height / 2;
        const cx = r.left + r.width / 2;
        if (cx < currentCenterX - 4) {
          const dx = cx - currentCenterX;
          const dy = cy - currentCenterY;
          const dist = Math.abs(dx) + Math.abs(dy) * 2;
          if (dist < bestDistance) {
            bestDistance = dist;
            bestMatch = el;
          }
        }
      });
      if (!bestMatch && currentIndex > 0) {
        bestMatch = focusables[currentIndex - 1];
      }
    } else if (e.key === 'ArrowRight') {
      focusables.forEach((el) => {
        if (el === target) return;
        const r = el.getBoundingClientRect();
        const cy = r.top + r.height / 2;
        const cx = r.left + r.width / 2;
        if (cx > currentCenterX + 4) {
          const dx = cx - currentCenterX;
          const dy = cy - currentCenterY;
          const dist = Math.abs(dx) + Math.abs(dy) * 2;
          if (dist < bestDistance) {
            bestDistance = dist;
            bestMatch = el;
          }
        }
      });
      if (!bestMatch && currentIndex < focusables.length - 1) {
        bestMatch = focusables[currentIndex + 1];
      }
    }

    if (bestMatch) {
      e.preventDefault();
      bestMatch.focus();
      if (bestMatch instanceof HTMLInputElement) {
        bestMatch.select();
      }
    }
  };

