    const cleanCode = newSellerCodeModal.trim().toUpperCase();
    const cleanName = newSellerNameModal.trim().toUpperCase();
    const exists = registeredSellers.some(s => (s.code || s.sellerCode) === cleanCode);
    const updated = exists
      ? registeredSellers.map(s => (s.code || s.sellerCode) === cleanCode ? { ...s, name: cleanName } : s)
      : [...registeredSellers, { id: `s-${Date.now()}`, code: cleanCode, name: cleanName }];
    setRegisteredSellers(updated);
    localStorage.setItem('MFI_SOA_SELLERS', JSON.stringify(updated));
