  // Sync Pallet dimensions when numberOfPallets or documentType changes
  useEffect(() => {
    if (data.documentType === 'PACKING LIST') {
      const numPallets = Math.max(1, parseInt(data.numberOfPallets as any) || 1);
      const currentDims = data.palletDimensions || [];
      if (currentDims.length !== numPallets) {
        const newDims = [...currentDims];
        if (newDims.length < numPallets) {
          while (newDims.length < numPallets) {
            newDims.push('');
          }
        } else {
          newDims.length = numPallets;
        }
        setData(prev => ({
          ...prev,
          palletDimensions: newDims
        }));
      }
    }
  }, [data.numberOfPallets, data.documentType]);

