                  const docTypeLabel = pdfPreviewDocType || (typeof pdfPreviewDoc.documentType === 'string' ? pdfPreviewDoc.documentType : 'TAX INVOICE');
                  const autoFileName = getFormattedDocTitle(docTypeLabel, pdfPreviewDoc);

                  if (previewElem) {
                    await downloadPdfFromHtml(previewElem.innerHTML, autoFileName);
                  } else {
                    handleTriggerDownloadPdf(pdfPreviewDocType || undefined, pdfPreviewDoc);
                  }
